    max_s = 0
    for _ in range(5):
        initial_a = np.random.rand(n) * 2
        res = minimize(objective, initial_a, method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            max_s = max(max_s, -res.fun)

    return max_s

