    # constraints:
    # x_i + y_i + x_{i+1} <= 2
    # y_i + x_{i+1} + y_{i+1} <= 2

    def objective(vars):
        x = vars[:m]
        y = vars[m:]
        s = 0
        for i in range(m):
            s += x[i] * x[(i+1)%m]
            s += y[i] * y[(i+1)%m]
        return -s

