    # x_i + y_i + x_{i+1} <= 2
    for i in range(m):
        def con1(vars, i=i):
            x = vars[:m]
            y = vars[m:]
            return 2 - (x[i] + y[i] + x[(i+1)%m])
        cons.append({'type': 'ineq', 'fun': con1})

    # y_i + x_{i+1} + y_{i+1} <= 2
    for i in range(m):
        def con2(vars, i=i):
            x = vars[:m]
            y = vars[m:]
            return 2 - (y[i] + x[(i+1)%m] + y[(i+1)%m])
        cons.append({'type': 'ineq', 'fun': con2})

    bounds = [(0, 2)] * (2*m)

