from scipy.optimize import minimize

def solve_n(n):
    def objective(a):
        s = 0
        for i in range(n):
            s += a[i] * a[(i + 2) % n]
        return -s

    # Need to define a function for the constraints that takes a list
    def constraint_func(a, i):
        return 2 - (a[i] + a[(i+1)%n] + a[(i+2)%n])

    cons = []
    for i in range(n):
        # Pass i as a default argument to capture its current value
        cons.append({'type': 'ineq', 'fun': constraint_func, 'args': (i,)})

    bounds = [(0, 2) for _ in range(n)]

    starts = []
    starts.append(np.array([1, 0] * (n // 2)))
    starts.append(np.array([2/3] * n))
    # Handle the 3-period one carefully
    if n % 3 == 0:
        starts.append(np.array([1, 1, 0] * (n // 3)))
    else:
        starts.append(np.array([1, 1, 0] * (n // 3 + 1))[:n])

    max_s = 0
    for start in starts:
        s_arr = start[:n]
        res = minimize(objective, s_arr, bounds=bounds, constraints=cons, method='SLSQP')
        if res.success:
            max_s = max(max_s, -res.fun)
    return max_s

